        END IF;
        IF NEW.valid_to IS NOT NULL THEN
            RAISE EXCEPTION 'instrument_classification: insert for % must be open (valid_to NULL)', NEW.symbol;
        END IF;
        RETURN NEW;
    ELSIF TG_OP = 'UPDATE' THEN
        today := classification_write_date();
        IF OLD.valid_to IS NOT NULL THEN
            RAISE EXCEPTION 'instrument_classification: row (%, %, %) is closed and immutable',
                OLD.symbol, OLD.scheme, OLD.valid_from;
        END IF;
        IF (NEW.symbol, NEW.scheme, NEW.code, NEW.valid_from, NEW.source_ref, NEW.created_at)
           IS DISTINCT FROM
           (OLD.symbol, OLD.scheme, OLD.code, OLD.valid_from, OLD.source_ref, OLD.created_at) THEN
            RAISE EXCEPTION 'instrument_classification: only valid_to may change (close the row, insert a new one)';
        END IF;
        IF NEW.valid_to IS DISTINCT FROM today THEN
            RAISE EXCEPTION 'instrument_classification: close % with valid_to = today % (got %)',
                OLD.symbol, today, NEW.valid_to;
        END IF;
        RETURN NEW;
    ELSE
        RAISE EXCEPTION 'instrument_classification is append-only: % is not allowed', TG_OP;
    END IF;
END $$;


ALTER FUNCTION public.instrument_classification_append_only() OWNER TO postgres;

--
-- Name: instruments_clear_eligibility_when_inactive(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.instruments_clear_eligibility_when_inactive() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.is_active IS NOT TRUE THEN
    NEW.compute_eligible := false;
    NEW.compute_eligible_1d := false;
    NEW.live_tradeable := false;
  END IF;
  RETURN NEW;
END
$$;


ALTER FUNCTION public.instruments_clear_eligibility_when_inactive() OWNER TO postgres;

--
-- Name: notify_instrument_change(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.notify_instrument_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    PERFORM pg_notify('instruments', COALESCE(NEW.symbol, OLD.symbol));
    RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION public.notify_instrument_change() OWNER TO postgres;

--
-- Name: ohlcv_d1_append_only(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ohlcv_d1_append_only() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    RAISE EXCEPTION '% is append-only: % is not allowed', TG_TABLE_NAME, TG_OP
        USING ERRCODE = 'check_violation';
END;
$$;


ALTER FUNCTION public.ohlcv_d1_append_only() OWNER TO postgres;

--
-- Name: FUNCTION ohlcv_d1_append_only(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.ohlcv_d1_append_only() IS 'Refuses UPDATE, DELETE (row triggers) and TRUNCATE (statement triggers) on the D1 tables ohlcv_request and ohlcv_observation (migration 380): raw answers are permanent, an answer that was seen cannot be unseen.';


--
-- Name: recompress_signal_ledger(integer, jsonb); Type: PROCEDURE; Schema: public; Owner: postgres
--

CREATE PROCEDURE public.recompress_signal_ledger(IN job_id integer, IN config jsonb)
    LANGUAGE plpgsql
    AS $$
DECLARE
  chunk_row record;
BEGIN
  FOR chunk_row IN
    SELECT chunk_schema, chunk_name
    FROM timescaledb_information.chunks
    WHERE hypertable_name = 'signal_ledger'
      AND is_compressed = true
      AND range_end < NOW() - INTERVAL '1 day'
  LOOP
    CALL recompress_chunk(format('%I.%I', chunk_row.chunk_schema, chunk_row.chunk_name)::regclass);
  END LOOP;
END;
$$;


ALTER PROCEDURE public.recompress_signal_ledger(IN job_id integer, IN config jsonb) OWNER TO postgres;

--
-- Name: update_signal_ledger_derived_columns(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.update_signal_ledger_derived_columns() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  NEW.effective_ts := COALESCE(NEW.signal_computed_at, NEW.feature_ts);

  IF NEW.signal_computed_at IS NOT NULL AND NEW.feature_ts IS NOT NULL THEN
    NEW.pipeline_lag_ms := EXTRACT(EPOCH FROM (NEW.signal_computed_at - NEW.feature_ts)) * 1000.0;
  ELSE
    NEW.pipeline_lag_ms := NULL;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.update_signal_ledger_derived_columns() OWNER TO postgres;

--
-- Name: weekly_db_maintenance(integer, jsonb); Type: PROCEDURE; Schema: public; Owner: postgres
--

CREATE PROCEDURE public.weekly_db_maintenance(IN job_id integer, IN config jsonb)
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- Refresh materialized views
  REFRESH MATERIALIZED VIEW CONCURRENTLY signal_stats_daily;

  -- Update planner statistics on all key tables
  ANALYZE intelligence_features;
  ANALYZE signal_ledger;
  ANALYZE llm_calls;
  ANALYZE market_data_ohlcv;
  ANALYZE signal_features;
  ANALYZE drift_monitor;
  ANALYZE signal_performance_segmented;
  ANALYZE setup_performance;

  -- Reset slow query stats for a fresh weekly window
  PERFORM pg_stat_statements_reset();

  RAISE NOTICE 'Weekly maintenance complete at %', now();
END;
$$;


ALTER PROCEDURE public.weekly_db_maintenance(IN job_id integer, IN config jsonb) OWNER TO postgres;

