--
-- Name: llm_calls; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.llm_calls (
    call_id uuid DEFAULT gen_random_uuid() NOT NULL,
    called_at timestamp with time zone NOT NULL,
    call_type text NOT NULL,
    signal_id uuid,
    group_name text,
    symbol text NOT NULL,
    timeframe text NOT NULL,
    model text NOT NULL,
    provider text NOT NULL,
    prompt text NOT NULL,
    response text,
    latency_ms integer,
    tokens_est integer,
    succeeded boolean DEFAULT true NOT NULL,
    regime text,
    session text,
    entry_price double precision,
    stop_loss double precision,
    target_price double precision,
    confidence double precision,
    cis_score double precision,
    entry_zone_low double precision,
    entry_zone_high double precision,
    setup_type text,
    outcome text,
    pnl_r double precision,
    mae double precision,
    mfe double precision,
    bars_in_trade integer,
    win boolean,
    outcome_at timestamp with time zone,
    agent_id text,
    prompt_version text,
    parse_success boolean DEFAULT true,
    failure_reason text
)
WITH (autovacuum_vacuum_scale_factor='0.05', autovacuum_analyze_scale_factor='0.02');


ALTER TABLE public.llm_calls OWNER TO postgres;

--
-- Name: TABLE llm_calls; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.llm_calls IS 'Audit log of every LLM call made by the intelligence layer. Partitioned by called_at for efficient time-range queries. Outcome columns (pnl_r, mae, mfe, win, outcome, outcome_at) are NULL at insert and back-filled when signal_lifecycle_service emits an exit event.';


--
-- Name: COLUMN llm_calls.call_type; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.llm_calls.call_type IS 'Invocation type: per_signal (ai_narrative per setup), group_synthesis (phi4-mini group), counterfactual (shadow/suppressed signal).';


--
-- Name: COLUMN llm_calls.signal_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.llm_calls.signal_id IS 'Soft reference to signal_ledger.signal_id (no FK — signal_ledger PK is composite). NULL for group_synthesis calls.';


--
-- Name: COLUMN llm_calls.provider; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.llm_calls.provider IS 'LLM provider name, e.g. ''ollama''. Supports multi-provider routing in future.';


--
-- Name: COLUMN llm_calls.succeeded; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.llm_calls.succeeded IS 'FALSE when the LLM call timed out, errored, or returned unparseable output.';


--
-- Name: COLUMN llm_calls.regime; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.llm_calls.regime IS 'Market regime at call time: trending | ranging | volatile. Copied from IntelligenceEvent.';


--
-- Name: COLUMN llm_calls.pnl_r; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.llm_calls.pnl_r IS 'Final P&L in units of initial risk (R). Back-filled from signal_lifecycle outcome.';


--
-- Name: COLUMN llm_calls.win; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.llm_calls.win IS 'TRUE if trade closed with pnl_r > 0. NULL until outcome is known.';


--
-- Name: COLUMN llm_calls.outcome_at; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.llm_calls.outcome_at IS 'Timestamp of signal exit / outcome determination. NULL until back-filled.';


