ALTER TABLE public.feature_vectors OWNER TO postgres;

--
-- Name: COLUMN feature_vectors.feature_vector_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.feature_vectors.feature_vector_id IS 'SHA-256(symbol|tf|bar_ts_ns|pipeline_version)[:32] as UUID. Content-addressed row key.
     Idempotent across replays. NULL for rows written before migration 158.
     Uniqueness guaranteed at application layer (SHA-256 collision resistance).';


--
-- Name: COLUMN feature_vectors.feature_factory_version; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.feature_vectors.feature_factory_version IS 'Algorithm version from FEATURE_FACTORY_VERSION in feature_factory.py.
     Bump on any compute change to prevent mixing IC estimates across algorithm versions.
     DEFAULT ''1.0.0'' applies to existing rows written before this migration.';


--
-- Name: COLUMN feature_vectors.bar_close_ts; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.feature_vectors.bar_close_ts IS 'Bar close timestamp. For intraday TFs: bar_ts + TF duration.
     For 1d: bar_ts + 1 day (daily bar closes at midnight UTC).
     NULL on pre-migration rows. Consider NOT NULL constraint in Phase 139.';


--
-- Name: COLUMN feature_vectors.momentum_z_slow; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.feature_vectors.momentum_z_slow IS 'Slow-scale return z-score (APR: feature.momentum.window_slow, default 60 bars).
     NULL on pre-migration rows written before 138-P1.';


--
-- Name: COLUMN feature_vectors.momentum_reversal_z; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.feature_vectors.momentum_reversal_z IS '1-bar log return z-score. Concept-named: captures short-term price shock magnitude.
     NULL on pre-migration rows written before 138-P1.';


--
-- Name: COLUMN feature_vectors.quarter_position; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.feature_vectors.quarter_position IS 'Position within calendar quarter [0, 1]. Captures earnings/rebalancing cycle.
     NULL on pre-migration rows written before 138-P1.';


--
-- Name: COLUMN feature_vectors.days_to_month_end; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.feature_vectors.days_to_month_end IS 'Normalized days remaining to month end [0, 1]. Captures window-dressing / month-turn effect.
     NULL on pre-migration rows written before 138-P1.';


--
-- Name: COLUMN feature_vectors.momentum_rank_z; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.feature_vectors.momentum_rank_z IS 'Cross-sectional momentum rank z-score across active universe.
     NULL = not yet enriched (populated in Phase 139 enrichment pass).';


--
-- Name: COLUMN feature_vectors.volume_rank_z; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.feature_vectors.volume_rank_z IS 'Cross-sectional volume rank z-score across active universe.
     NULL = not yet enriched (populated in Phase 139 enrichment pass).';


--
-- Name: COLUMN feature_vectors.volatility_rank_z; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.feature_vectors.volatility_rank_z IS 'Cross-sectional volatility rank z-score across active universe.
     NULL = not yet enriched (populated in Phase 139 enrichment pass).';


--
-- Name: COLUMN feature_vectors.regime_rolling; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.feature_vectors.regime_rolling IS 'EXPERIMENTAL — Shadow regime column for HMM rolling refit testing (docs/experiments/2024-06-29-hmm-rolling-refit-pilot.md). NOT PRODUCTION DATA. Do NOT use in IC engine or downstream processes until validated. Canonical regime is in ''regime'' column.';


--
-- Name: COLUMN feature_vectors.hmm_churn; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.feature_vectors.hmm_churn IS 'Rolling label-change rate over the prior feature.hmm.churn_window bars (P2c). 1.0 = every bar in the window changed regime label; 0.0 = fully stable. NULL until regime_writer.py re-labels the row. High churn signals boundary oscillation the LIFECYCLE-04 regime-shift guard must be able to distinguish from a genuine regime shift.';


--
-- Name: COLUMN feature_vectors.dist_from_high_fast; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.feature_vectors.dist_from_high_fast IS 'Distance from rolling high, ATR-normalized: (rolling_high_N - C) / ATR. Unbounded non-negative. APR: feature.breakout.dist_window_fast.';


--
-- Name: COLUMN feature_vectors.dist_from_high_slow; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.feature_vectors.dist_from_high_slow IS 'Distance from rolling high, ATR-normalized: (rolling_high_N - C) / ATR. Unbounded non-negative. APR: feature.breakout.dist_window_slow.';


--
-- Name: COLUMN feature_vectors.dist_from_low_fast; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.feature_vectors.dist_from_low_fast IS 'Distance from rolling low, ATR-normalized: (C - rolling_low_N) / ATR. Unbounded non-negative. APR: feature.breakout.dist_window_fast.';


--
-- Name: COLUMN feature_vectors.dist_from_low_slow; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.feature_vectors.dist_from_low_slow IS 'Distance from rolling low, ATR-normalized: (C - rolling_low_N) / ATR. Unbounded non-negative. APR: feature.breakout.dist_window_slow.';


--
-- Name: COLUMN feature_vectors.range_pct_fast; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.feature_vectors.range_pct_fast IS 'Rolling range as a fraction of price: (rolling_high_N - rolling_low_N) / C. Unbounded non-negative. APR: feature.breakout.range_window_fast.';


--
-- Name: COLUMN feature_vectors.range_pct_slow; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.feature_vectors.range_pct_slow IS 'Rolling range as a fraction of price: (rolling_high_N - rolling_low_N) / C. Unbounded non-negative. APR: feature.breakout.range_window_slow.';


--
-- Name: COLUMN feature_vectors.stoch_k_fast; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.feature_vectors.stoch_k_fast IS 'Stochastic %K: (C - L_N) / (H_N - L_N). Bounded [0,1]; 0.5 on degenerate range. APR: feature.breakout.stoch_window_fast.';


--
-- Name: COLUMN feature_vectors.stoch_k_slow; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.feature_vectors.stoch_k_slow IS 'Stochastic %K: (C - L_N) / (H_N - L_N). Bounded [0,1]; 0.5 on degenerate range. APR: feature.breakout.stoch_window_slow.';


--
-- Name: COLUMN feature_vectors.price_percentile_fast; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.feature_vectors.price_percentile_fast IS 'Rolling percentile rank of C_t within the trailing window. Bounded [0,1]. APR: feature.breakout.percentile_window_fast.';


--
-- Name: COLUMN feature_vectors.price_percentile_slow; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.feature_vectors.price_percentile_slow IS 'Rolling percentile rank of C_t within the trailing window. Bounded [0,1]. APR: feature.breakout.percentile_window_slow.';


--
-- Name: COLUMN feature_vectors.efficiency_ratio_fast; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.feature_vectors.efficiency_ratio_fast IS 'Kaufman efficiency ratio: |C_t - C_t-N| / sum(|C_i - C_i-1|). Bounded [0,1] (0=chop, 1=linear trend). APR: feature.breakout.efficiency_window_fast.';


--
-- Name: COLUMN feature_vectors.efficiency_ratio_slow; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.feature_vectors.efficiency_ratio_slow IS 'Kaufman efficiency ratio: |C_t - C_t-N| / sum(|C_i - C_i-1|). Bounded [0,1] (0=chop, 1=linear trend). APR: feature.breakout.efficiency_window_slow.';


--
-- Name: COLUMN feature_vectors.body_ratio; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.feature_vectors.body_ratio IS '(C - O) / (H - L), bounded [-1, 1]. Directional conviction of the bar.';


--
-- Name: COLUMN feature_vectors.upper_wick_ratio; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.feature_vectors.upper_wick_ratio IS '(H - max(O,C)) / (H - L), bounded [0, 1].';


--
-- Name: COLUMN feature_vectors.lower_wick_ratio; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.feature_vectors.lower_wick_ratio IS '(min(O,C) - L) / (H - L), bounded [0, 1].';


--
-- Name: COLUMN feature_vectors.range_vs_atr; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.feature_vectors.range_vs_atr IS '(H - L) / ATR_N, unbounded non-negative.';


--
-- Name: COLUMN feature_vectors.close_vs_open_direction; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.feature_vectors.close_vs_open_direction IS 'sign(C - O), categorical {-1, 0, 1}.';


--
-- Name: COLUMN feature_vectors.overnight_gap; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.feature_vectors.overnight_gap IS '(O - prev_C) / prev_C, unbounded. APR: feature.overnight_gap.window (via overnight_gap_z).';


--
-- Name: COLUMN feature_vectors.overnight_gap_z; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.feature_vectors.overnight_gap_z IS 'Z-score of overnight_gap. APR: feature.overnight_gap.window.';


--
-- Name: COLUMN feature_vectors.range_efficiency; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.feature_vectors.range_efficiency IS 'abs(C - prev_C) / (H - L), bounded [0, 1].';


--
-- Name: COLUMN feature_vectors.ret_lag_1; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.feature_vectors.ret_lag_1 IS 'log(C_t / C_t-1), definitional.';


--
-- Name: COLUMN feature_vectors.ret_lag_2; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.feature_vectors.ret_lag_2 IS 'log(C_t / C_t-2), definitional.';


--
-- Name: COLUMN feature_vectors.ret_lag_3; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.feature_vectors.ret_lag_3 IS 'log(C_t / C_t-3), definitional.';


--
-- Name: COLUMN feature_vectors.ret_lag_fast; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.feature_vectors.ret_lag_fast IS 'log(C_t / C_t-N). APR: feature.ret_lag.fast.';


--
-- Name: COLUMN feature_vectors.ret_lag_mid; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.feature_vectors.ret_lag_mid IS 'log(C_t / C_t-N). APR: feature.ret_lag.mid.';


--
-- Name: COLUMN feature_vectors.ret_lag_slow; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.feature_vectors.ret_lag_slow IS 'log(C_t / C_t-N). APR: feature.ret_lag.slow.';


--
-- Name: COLUMN feature_vectors.open_ret; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.feature_vectors.open_ret IS 'log(O_t / prev_C), overnight component, unbounded.';


--
-- Name: COLUMN feature_vectors.intraday_ret; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.feature_vectors.intraday_ret IS 'log(C_t / O_t), intraday component, unbounded.';


--
-- Name: COLUMN feature_vectors.open_vs_intraday; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.feature_vectors.open_vs_intraday IS 'open_ret - intraday_ret, unbounded.';


--
-- Name: COLUMN feature_vectors.session_time_pos; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.feature_vectors.session_time_pos IS 'Continuous [0, 1] position within the NY session.';


--
-- Name: COLUMN feature_vectors.hour_of_day_sin; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.feature_vectors.hour_of_day_sin IS 'sin(2*pi*(hour+minute/60)/24), bounded [-1, 1].';


--
-- Name: COLUMN feature_vectors.hour_of_day_cos; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.feature_vectors.hour_of_day_cos IS 'cos(2*pi*(hour+minute/60)/24), bounded [-1, 1].';


--
-- Name: COLUMN feature_vectors.week_of_month_sin; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.feature_vectors.week_of_month_sin IS 'sin(2*pi*week/5), week=(day-1)//7+1, bounded [-1, 1].';


--
-- Name: COLUMN feature_vectors.week_of_month_cos; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.feature_vectors.week_of_month_cos IS 'cos(2*pi*week/5), bounded [-1, 1].';


--
-- Name: COLUMN feature_vectors.day_of_month_sin; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.feature_vectors.day_of_month_sin IS 'sin(2*pi*day/31), bounded [-1, 1].';


--
-- Name: COLUMN feature_vectors.day_of_month_cos; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.feature_vectors.day_of_month_cos IS 'cos(2*pi*day/31), bounded [-1, 1].';


--
-- Name: COLUMN feature_vectors.week_of_year_sin; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.feature_vectors.week_of_year_sin IS 'sin(2*pi*isocalendar_week/52), bounded [-1, 1].';


--
-- Name: COLUMN feature_vectors.week_of_year_cos; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.feature_vectors.week_of_year_cos IS 'cos(2*pi*isocalendar_week/52), bounded [-1, 1].';


--
-- Name: COLUMN feature_vectors.month_sin; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.feature_vectors.month_sin IS 'sin(2*pi*month/12), bounded [-1, 1].';


--
-- Name: COLUMN feature_vectors.month_cos; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.feature_vectors.month_cos IS 'cos(2*pi*month/12), bounded [-1, 1].';


--
-- Name: COLUMN feature_vectors.vol_acceleration; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.feature_vectors.vol_acceleration IS 'V_t / V_t-1, unbounded positive.';


--
-- Name: COLUMN feature_vectors.dollar_vol_z; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.feature_vectors.dollar_vol_z IS 'Z-score of (V*C). APR: feature.dollar_vol.window.';


--
-- Name: COLUMN feature_vectors.vol_range_ratio; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.feature_vectors.vol_range_ratio IS 'V_t / (H-L) normalized over N. APR: feature.vol_range_ratio.window.';


--
-- Name: COLUMN feature_vectors.vol_trend_ratio; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.feature_vectors.vol_trend_ratio IS 'vol_MA_fast / vol_MA_slow. APR: feature.vol_trend.fast/.slow.';


--
-- Name: COLUMN feature_vectors.up_vol_ratio_fast; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.feature_vectors.up_vol_ratio_fast IS 'sum(V|C>O)/sum(V), bounded [0,1]. APR: feature.up_vol_ratio.fast.';


--
-- Name: COLUMN feature_vectors.up_vol_ratio_slow; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.feature_vectors.up_vol_ratio_slow IS 'sum(V|C>O)/sum(V), bounded [0,1]. APR: feature.up_vol_ratio.slow.';


--
-- Name: COLUMN feature_vectors.vol_percentile; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.feature_vectors.vol_percentile IS 'Rolling percentile rank of V_t, bounded [0,1]. APR: feature.vol_percentile.window.';


--
-- Name: COLUMN feature_vectors.vol_persistence; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.feature_vectors.vol_persistence IS 'Lag-1 autocorrelation of V, bounded [-1,1]. APR: feature.vol_persistence.window.';


--
-- Name: COLUMN feature_vectors.vol_std_z; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.feature_vectors.vol_std_z IS 'Z-score of rolling std(V). APR: feature.vol_std.window.';


--
-- Name: COLUMN feature_vectors.mfi_fast; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.feature_vectors.mfi_fast IS 'Money Flow Index, bounded [0,100]. APR: feature.mfi.fast.';


--
-- Name: COLUMN feature_vectors.mfi_slow; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.feature_vectors.mfi_slow IS 'Money Flow Index, bounded [0,100]. APR: feature.mfi.slow.';


--
-- Name: COLUMN feature_vectors.obv_z; Type: COMMENT; Schema: public; Owner: postgres
--

