--
-- Name: alpha_multiplier_shadow; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.alpha_multiplier_shadow (
    ts timestamp with time zone NOT NULL,
    signal_id uuid NOT NULL,
    agent_id text NOT NULL,
    symbol text NOT NULL,
    tf text NOT NULL,
    hmm_regime integer,
    path text NOT NULL,
    predicted_multiplier double precision NOT NULL,
    confidence double precision NOT NULL,
    features jsonb,
    id bigint NOT NULL
);


ALTER TABLE public.alpha_multiplier_shadow OWNER TO postgres;

--
-- Name: TABLE alpha_multiplier_shadow; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.alpha_multiplier_shadow IS 'Shadow multiplier predictions per swarm agent per signal. One row per (signal_id, agent_id) by application convention. Keep forever — training dataset. JOIN signal_ledger ON (signal_id) for outcome-labeled rows. Pearson(confidence, win_flag) per segment for promotion validation.';


--
-- Name: alpha_multiplier_shadow_id_seq; Type: SEQUENCE; Schema: public; Owner: postgres
--

ALTER TABLE public.alpha_multiplier_shadow ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.alpha_multiplier_shadow_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


--
-- Name: backfill_status; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.backfill_status (
    symbol text NOT NULL,
    tf text NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    fetch_complete boolean DEFAULT false NOT NULL,
    rows_written bigint,
    theoretical_max bigint,
    started_at timestamp with time zone,
    completed_at timestamp with time zone,
    error_msg text,
    CONSTRAINT backfill_status_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'in_progress'::text, 'complete'::text, 'failed'::text])))
);


ALTER TABLE public.backfill_status OWNER TO postgres;

--
-- Name: bar_content_digest; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.bar_content_digest (
    symbol text NOT NULL,
    timeframe text NOT NULL,
    range_start timestamp with time zone NOT NULL,
    range_end timestamp with time zone NOT NULL,
    digest text NOT NULL,
    algorithm text NOT NULL,
    rule_version text NOT NULL,
    n_rows integer NOT NULL,
    batch_id uuid,
    computed_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT bar_content_digest_n_rows_check CHECK ((n_rows >= 0))
);


ALTER TABLE public.bar_content_digest OWNER TO postgres;

--
-- Name: TABLE bar_content_digest; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.bar_content_digest IS 'Append-only bar content digests per (symbol, timeframe, calendar month) for 5m, 15m and 1h (migration 383, D-07): sha256-bars-v1 over values plus flag state, computed by src/intelligence/bars/digest.py. The rule version sits beside the digest and is deliberately not an input to it. Phase 186 revision detection reads bar_content_digest_current, never this table directly. Permanent: UPDATE, DELETE and TRUNCATE raise.';


--
-- Name: bar_content_digest_current; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.bar_content_digest_current AS
 SELECT DISTINCT ON (symbol, timeframe, range_start) symbol,
    timeframe,
    range_start,
    range_end,
    digest,
    algorithm,
    rule_version,
    n_rows,
    batch_id,
    computed_at
   FROM public.bar_content_digest
  ORDER BY symbol, timeframe, range_start, computed_at DESC;


ALTER VIEW public.bar_content_digest_current OWNER TO postgres;

--
-- Name: VIEW bar_content_digest_current; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON VIEW public.bar_content_digest_current IS 'Latest bar_content_digest row per (symbol, timeframe, range_start): the revision-detection surface phase 186 consumes and bar_derivation --stage grid --changed-only compares against.';


--
-- Name: bar_derivation_batch; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.bar_derivation_batch (
    batch_id uuid NOT NULL,
    stage text NOT NULL,
    rule_version text NOT NULL,
    code_commit text NOT NULL,
    apr_snapshot jsonb NOT NULL,
    n_symbols integer,
    status text NOT NULL,
    started_at timestamp with time zone NOT NULL,
    finished_at timestamp with time zone,
    detail jsonb DEFAULT '{}'::jsonb NOT NULL,
    CONSTRAINT bar_derivation_batch_stage_check CHECK ((stage = ANY (ARRAY['scrub'::text, 'grid'::text, 'daily'::text, 'seam_audit'::text, 'listing_venue'::text, 'legacy'::text]))),
    CONSTRAINT bar_derivation_batch_status_check CHECK ((status = ANY (ARRAY['running'::text, 'completed'::text, 'failed'::text])))
);


ALTER TABLE public.bar_derivation_batch OWNER TO postgres;

--
-- Name: TABLE bar_derivation_batch; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.bar_derivation_batch IS 'Provenance for every derivation-side run (scrub, grid, daily, seam audit, listing venue, legacy imports): stage, rule version, code commit, APR snapshot, status. Single writer role bar_derivation_writer.';


--
-- Name: bar_quality_flag; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.bar_quality_flag (
    symbol text NOT NULL,
    timeframe text NOT NULL,
    "timestamp" timestamp with time zone NOT NULL,
    rule text NOT NULL,
