ALTER SEQUENCE public.dlq_events_id_seq OWNER TO postgres;

--
-- Name: dlq_events_id_seq; Type: SEQUENCE OWNED BY; Schema: public; Owner: postgres
--

ALTER SEQUENCE public.dlq_events_id_seq OWNED BY public.dlq_events.id;


