-- Name: TABLE drift_state; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.drift_state IS 'KS distribution drift and CUSUM performance drift severity per symbol/TF or setup_plugin. Written by drift_monitor_service; read by signal_generator_service at startup and every 4h.';


--
-- Name: economic_series_observation; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.economic_series_observation (
    series_id text CONSTRAINT macro_series_observations_series_id_not_null NOT NULL,
    observation_date date CONSTRAINT macro_series_observations_observation_date_not_null NOT NULL,
    value double precision CONSTRAINT macro_series_observations_value_not_null NOT NULL,
    available_at timestamp with time zone CONSTRAINT macro_series_observations_available_at_not_null NOT NULL,
    availability_basis text CONSTRAINT macro_series_observations_availability_basis_not_null NOT NULL,
    compute_version text CONSTRAINT macro_series_observations_compute_version_not_null NOT NULL,
    fetched_at timestamp with time zone DEFAULT now() CONSTRAINT macro_series_observations_derived_at_not_null NOT NULL,
    source text CONSTRAINT macro_series_observation_source_not_null NOT NULL,
    CONSTRAINT economic_series_observation_availability_basis_check CHECK ((availability_basis = ANY (ARRAY['assumed_lag'::text, 'fetch'::text]))),
    CONSTRAINT economic_series_observation_finite CHECK (((value <> 'NaN'::double precision) AND (value <> 'Infinity'::double precision) AND (value <> '-Infinity'::double precision))),
    CONSTRAINT economic_series_observation_source_check CHECK ((source = ANY (ARRAY['fred'::text, 'nyfed'::text, 'yahoo'::text])))
);


ALTER TABLE public.economic_series_observation OWNER TO postgres;

--
-- Name: TABLE economic_series_observation; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.economic_series_observation IS 'FRED observations, append-only (todo 480). A revision is a new row with a later available_at. Readers take the latest available_at <= t per observation date; use economic_series_observation_current for the latest known value.';


--
-- Name: economic_series_observation_coverage; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.economic_series_observation_coverage (
    series_id text CONSTRAINT macro_series_coverage_series_id_not_null NOT NULL,
    covered_from date CONSTRAINT macro_series_coverage_covered_from_not_null NOT NULL,
    covered_to date CONSTRAINT macro_series_coverage_covered_to_not_null NOT NULL,
    checked_at timestamp with time zone CONSTRAINT macro_series_coverage_checked_at_not_null NOT NULL,
    unit text NOT NULL
);


ALTER TABLE public.economic_series_observation_coverage OWNER TO postgres;

--
-- Name: TABLE economic_series_observation_coverage; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.economic_series_observation_coverage IS 'Per series: its declared unit and the span of observation dates any fetch has examined (todo 480). The unit is declared by the provider (FRED metadata, or the NY Fed field map), never inferred from a value, and a run fails if it changes. A day outside the span is unknown, not missing.';


--
-- Name: economic_series_observation_current; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.economic_series_observation_current AS
 SELECT DISTINCT ON (o.series_id, o.observation_date) o.source,
    o.series_id,
    o.observation_date,
    o.value,
    c.unit,
    o.available_at,
    o.availability_basis
   FROM (public.economic_series_observation o
     JOIN public.economic_series_observation_coverage c USING (series_id))
  ORDER BY o.series_id, o.observation_date, o.available_at DESC;


ALTER VIEW public.economic_series_observation_current OWNER TO postgres;

--
-- Name: VIEW economic_series_observation_current; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON VIEW public.economic_series_observation_current IS 'Latest known value per series and observation date, with its declared unit (todo 480). Not point in time: for a read as of t, filter economic_series_observation on available_at <= t first.';


