    CONSTRAINT feature_ic_scores_v2_shrinkage_weight_unit_interval_chk CHECK (((shrinkage_weight IS NULL) OR ((shrinkage_weight >= (0)::double precision) AND (shrinkage_weight <= (1)::double precision))))
