ALTER TABLE public.gate_evaluations OWNER TO postgres;

--
-- Name: ic_cell_fingerprints; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.ic_cell_fingerprints (
    symbol text NOT NULL,
    tf text NOT NULL,
    pass_type text NOT NULL,
    training_window_end timestamp with time zone NOT NULL,
    code_content_key text NOT NULL,
    apr_snapshot_key text NOT NULL,
    upstream_watermark jsonb NOT NULL,
    computed_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ic_cell_fingerprints_pass_type_check CHECK ((pass_type = ANY (ARRAY['pooled'::text, 'symbol_hmm'::text, 'cross_sectional'::text])))
);


ALTER TABLE public.ic_cell_fingerprints OWNER TO postgres;

--
-- Name: TABLE ic_cell_fingerprints; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.ic_cell_fingerprints IS 'Whole-cell skip/recompute fingerprint for ic_engine.py (Phase 162 Plan 03, todo 134). A cell (one row) is skip-eligible for a re-run ONLY when ALL THREE of code_content_key, apr_snapshot_key, and upstream_watermark match the freshly-computed current values -- a partial match is a full miss (crash-loud, never silently partial-stale). code_content_key: SHA-256 of first-party src/services bytes actually imported (_checkpoint_content_key(), 12 hex). apr_snapshot_key: BaseBatch.content_key() over the sorted COMPUTATIONAL-only ICEngineConfig fields (_compute_apr_snapshot_key()) -- an OPERATIONAL field (thread counts, chunk sizes, throughput knobs) changing must NEVER move this key. upstream_watermark: per-table JSONB watermark (forward_returns MAX(computed_at) + feature_vectors/market_regimes/instrument_tags/feature_registry content hashes) that changes on an in-place VALUE mutation even when MAX(bar_ts)/COUNT(*) are unchanged (see _compute_upstream_watermark()). For pass_type=''cross_sectional'', symbol is a synthesized ''{regime_group}:{regime_label}'' key, NOT feature_ic_scores.symbol (which is always the ''POOLED'' sentinel for those rows) -- see this migration''s header comment for why.';


--
-- Name: instrument_annotations; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.instrument_annotations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    symbol text NOT NULL,
    annotation_type text NOT NULL,
    content text NOT NULL,
    source text NOT NULL,
    model_id text,
    confidence double precision,
    valid_from timestamp with time zone DEFAULT now() NOT NULL,
    valid_to timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT instrument_annotations_annotation_type_check CHECK ((annotation_type = ANY (ARRAY['thesis'::text, 'signal_context'::text, 'ai_insight'::text, 'regime_note'::text]))),
    CONSTRAINT instrument_annotations_confidence_check CHECK (((confidence >= (0.0)::double precision) AND (confidence <= (1.0)::double precision))),
    CONSTRAINT instrument_annotations_source_check CHECK ((source = ANY (ARRAY['human'::text, 'ai'::text])))
);


ALTER TABLE public.instrument_annotations OWNER TO postgres;

