);


ALTER TABLE public.instrument_metadata OWNER TO postgres;

--
-- Name: instrument_tags; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.instrument_tags (
    symbol text NOT NULL,
    tag text NOT NULL,
    weight double precision DEFAULT 1.0 NOT NULL,
    source text DEFAULT 'human'::text NOT NULL,
    evidence jsonb,
    assigned_at timestamp with time zone DEFAULT now() NOT NULL,
    loading double precision,
    p_value double precision,
    bh_adjusted_p double precision,
    passes_fdr boolean,
    consecutive_fails integer DEFAULT 0 NOT NULL,
    sample_n integer,
    estimated_at timestamp with time zone,
    valid_from timestamp with time zone DEFAULT now() NOT NULL,
    valid_to timestamp with time zone,
    partial_loading double precision,
    partial_loading_ci_low double precision,
    incremental_r2 double precision,
    sign_stable_windows integer,
    sign_stable_windows_total integer,
    null_arm_p_value double precision,
    null_arm_bh_p double precision,
    materiality_sample_n integer,
    passes_materiality boolean,
    discovery_state text,
    first_measured_at timestamp with time zone,
    CONSTRAINT instrument_tags_discovery_state_check CHECK (((discovery_state IS NULL) OR (discovery_state = ANY (ARRAY['pending_oos'::text, 'confirmed'::text])))),
    CONSTRAINT instrument_tags_source_check CHECK ((source = ANY (ARRAY['human'::text, 'empirical'::text, 'ai'::text]))),
    CONSTRAINT instrument_tags_weight_check CHECK (((weight >= (0.0)::double precision) AND (weight <= (1.0)::double precision)))
);


ALTER TABLE public.instrument_tags OWNER TO postgres;

--
-- Name: COLUMN instrument_tags.partial_loading; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.instrument_tags.partial_loading IS 'Pass 4: OLS beta of the (symbol, tag) loading after orthogonalizing against the control factor set (control_factor_series). The materiality-filtered replacement for a raw, unconditioned loading.';


--
-- Name: COLUMN instrument_tags.partial_loading_ci_low; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.instrument_tags.partial_loading_ci_low IS 'Pass 4: lower bound of the confidence interval around partial_loading (Codex''s R-05 lower-CI gate). A real column and a real gate, not dropped.';


--
-- Name: COLUMN instrument_tags.incremental_r2; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.instrument_tags.incremental_r2 IS 'Pass 4: incremental R-squared contributed by this tag''s factor_series beyond the control set alone -- the explanatory-power component of the materiality gate.';


--
-- Name: COLUMN instrument_tags.sign_stable_windows; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.instrument_tags.sign_stable_windows IS 'Pass 4: count of rolling measurement windows (out of sign_stable_windows_total) in which partial_loading''s sign matched the run-level sign -- the D-06 sign-stability component.';


--
-- Name: COLUMN instrument_tags.sign_stable_windows_total; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.instrument_tags.sign_stable_windows_total IS 'Pass 4: total number of rolling measurement windows evaluated for sign stability. Denominator for sign_stable_windows.';


--
-- Name: COLUMN instrument_tags.null_arm_p_value; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.instrument_tags.null_arm_p_value IS 'Pass 4: raw p-value from the D-06 circular-shift null-arm control for this (symbol, tag) pair, before BH-FDR adjustment.';


--
-- Name: COLUMN instrument_tags.null_arm_bh_p; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.instrument_tags.null_arm_bh_p IS 'Pass 4: Benjamini-Hochberg run-level FDR-adjusted null_arm_p_value.';


--
-- Name: COLUMN instrument_tags.materiality_sample_n; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.instrument_tags.materiality_sample_n IS 'Pass 4''s own post-control-alignment observation count -- distinct from sample_n, which is Pass 1''s bivariate alignment count. The two counts measure different alignments and must not be conflated.';


--
-- Name: COLUMN instrument_tags.passes_materiality; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.instrument_tags.passes_materiality IS 'Pass 4: the STATISTICAL gate only (R-04). Readers MUST additionally AND this with discovery_state = ''confirmed'' (the temporal gate, todo 125) and valid_to IS NULL (the expiry gate, todo 126) -- the three gates are stored separately, not collapsed, so a future per-consumer cutover can calibrate its own bar.';


--
-- Name: COLUMN instrument_tags.discovery_state; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.instrument_tags.discovery_state IS 'todo 125: typed promotion of the discovery-state concept out of the evidence JSONB blob. NULL until TagCalibrator''s next run backfills it; otherwise ''pending_oos'' or ''confirmed''. The temporal gate referenced by passes_materiality''s comment (R-04).';


--
-- Name: COLUMN instrument_tags.first_measured_at; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.instrument_tags.first_measured_at IS 'todo 125: typed promotion of the first-measurement timestamp out of the evidence JSONB blob -- the anchor discovery_oos_days counts forward from.';


--
-- Name: instrument_tags_active; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.instrument_tags_active AS
 SELECT symbol,
    tag,
    weight,
    source,
    evidence,
    assigned_at,
    loading,
    p_value,
    bh_adjusted_p,
    passes_fdr,
    consecutive_fails,
    sample_n,
    estimated_at,
    valid_from,
    valid_to,
    partial_loading,
    partial_loading_ci_low,
    incremental_r2,
    sign_stable_windows,
    sign_stable_windows_total,
    null_arm_p_value,
    null_arm_bh_p,
    materiality_sample_n,
    passes_materiality,
    discovery_state,
    first_measured_at
   FROM public.instrument_tags
  WHERE (valid_to IS NULL);


ALTER VIEW public.instrument_tags_active OWNER TO postgres;

--
-- Name: VIEW instrument_tags_active; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON VIEW public.instrument_tags_active IS 'todo 126: the required read path for any tag-membership query. Returns only unexpired (valid_to IS NULL) instrument_tags rows.';


