--
-- Name: VIEW market_data_ohlcv_scrub_input; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON VIEW public.market_data_ohlcv_scrub_input IS 'For the D2a scrub and D5 seam stages only: every traded bar (volume > 0, all sources, quarantined bars included). Every other reader uses market_data_ohlcv_tradeable.';


--
-- Name: market_data_ohlcv_tradeable; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.market_data_ohlcv_tradeable AS
 SELECT "timestamp",
    symbol,
    timeframe,
    open,
    high,
    low,
    close,
        CASE
            WHEN (source = 'ibkr_venue'::text) THEN NULL::bigint
            ELSE volume
        END AS volume,
    source,
    base,
    price_sanity_status
   FROM public.market_data_ohlcv
  WHERE ((volume > 0) AND (price_sanity_status IS DISTINCT FROM 'confirmed_corrupt'::text) AND (NOT (EXISTS ( SELECT 1
           FROM public.bar_quality_flag q
          WHERE (q.quarantine AND (q.symbol = market_data_ohlcv.symbol) AND (q.timeframe = market_data_ohlcv.timeframe) AND (q."timestamp" = market_data_ohlcv."timestamp"))))));


ALTER VIEW public.market_data_ohlcv_tradeable OWNER TO postgres;

--
-- Name: VIEW market_data_ohlcv_tradeable; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON VIEW public.market_data_ohlcv_tradeable IS 'Compute/measurement read boundary: traded bars (volume > 0), venue volume nulled, confirmed_corrupt and quarantine-flagged bars (bar_quality_flag) excluded. Raw-table access outside this needs a test_market_data_ohlcv_boundary.py allow-list entry.';


